import os
for f in sorted(os.listdir('.')):
    if f.endswith(('.tex', '.bib', '.sty', '.cls', '.bst')):
        try:
            data = open(f, 'rb').read()
            for i, b in enumerate(data):
                if b > 127:
                    line_num = data[:i].count(b'\n') + 1
                    context = data[max(0,i-20):i+20]
                    print(f'{f}:{line_num} pos={i} byte=0x{b:02x} context={context}')
        except Exception as e:
            print(f'{f}: ERROR {e}')
